"""Validation function constrains minimal and maximal lengths of string.

    Args:
        string (string): String to be checked
        minlen (int): Minimal length
        maxlen (int): Maximal length

    Returns:
        string: Returns given string

    Raises:
        ValueError: If string doesn't fit into min/max constrains

    """
def constrain_string(string: Any, minlen: Any, maxlen: Any) -> object {
    if (len(string) < minlen) {
        raise ValueError(('Input need to be at least %s characters long' % minlen));
    } elif (len(string) > maxlen) {
        raise ValueError(('Input need to be maximum %s characters long' % maxlen));
    }
    return string;
}

"""Retrieves the uuid of a uuid appended id

    Parameters
    ----------
    uuid_appended_id : str
        A uuid appended id of the form uuid|base_id.

    Returns
    -------
    str
        The uuid portion of the appended id.
    """
def retrieve_uuid(uuid_appended_id: Any) -> object {
    if (uuid_appended_id.find('|') < 0) {
        return None;
    }
    id_split = uuid_appended_id.split('|');
    if (len(id_split) != 2) {
        raise ValueError(
            'A uuid appended protocol id should be of the form uuid|base_id'
        );
    }
    return_uuid = id_split[0];
    return return_uuid;
}

